// weight e (0..31) of an IQ2_XXS 32-block (its 8 bytes at p: u32 grid indices, u32 signs + scale), block scale d
__device__ __forceinline__ float iq2_value(const uint8_t *p, float d, int e) {
  unsigned g = p[0] | p[1] << 8 | p[2] << 16 | (unsigned)p[3] << 24, sg = p[4] | p[5] << 8 | p[6] << 16 | (unsigned)p[7] << 24;
  int l = e >> 3, j = e & 7;
  float v = d * (0.5f + (float)(sg >> 28)) * 0.25f * (float)((iq2xxs_grid[(g >> (8 * l)) & 255] >> (8 * j)) & 255);
  return (ksigns_iq2xs[(sg >> (7 * l)) & 127] >> j) & 1 ? -v : v;
}

