// weight e (0..255) of an IQ1_S 256-block at blk: d (2s + 1) (grid +- 1/8)
__device__ __forceinline__ float iq1s_value(const uint8_t *blk, int e) {
  int ib = e >> 5, l = (e >> 3) & 3, j = e & 7;
  unsigned qh = blk[34 + 2 * ib] | blk[35 + 2 * ib] << 8;
  float dl = __half2float(*(const __half *)blk) * (float)(2 * ((qh >> 12) & 7) + 1);
  int g = (int)(int8_t)((iq1s_grid[blk[2 + 4 * ib + l] | ((qh >> (3 * l)) & 7) << 8] >> (8 * j)) & 255);
  return dl * ((float)g + ((qh & 0x8000) ? -0.125f : 0.125f));
}

// weight e of an IQ2_XS 256-block (d, qs u16[32]: 9-bit grid + 7-bit sign index, scales[8]: two 4-bit per 32)
__device__ __forceinline__ float iq2xs_value(const uint8_t *blk, int e) {
  int ib = e >> 5, l = (e >> 3) & 3, j = e & 7;
  unsigned q = blk[2 + 2 * (4 * ib + l)] | blk[3 + 2 * (4 * ib + l)] << 8;
  unsigned sc = blk[66 + ib];
  float db = __half2float(*(const __half *)blk) * (0.5f + (float)((l < 2 ? sc : sc >> 4) & 15)) * 0.25f;
  float v = db * (float)((iq2xs_grid[q & 511] >> (8 * j)) & 255);
  return (ksigns_iq2xs[q >> 9] >> j) & 1 ? -v : v;
}

// weight e of an IQ2_S 256-block (d, qs[32] grid low bytes, signs[32], qh[8]: 2 high bits per group, scales[8])
__device__ __forceinline__ float iq2s_value(const uint8_t *blk, int e) {
  int ib = e >> 5, l = (e >> 3) & 3, j = e & 7;
  unsigned sc = blk[74 + ib];
  float db = __half2float(*(const __half *)blk) * (0.5f + (float)((l < 2 ? sc : sc >> 4) & 15)) * 0.25f;
  unsigned idx = blk[2 + 4 * ib + l] | ((blk[66 + ib] << (8 - 2 * l)) & 0x300);
  float v = db * (float)((iq2s_grid[idx] >> (8 * j)) & 255);
  return (blk[34 + 4 * ib + l] >> j) & 1 ? -v : v;
}

